<?php
define('CSRFCHECK_WITH_TOKEN', 1);
require $_SERVER['DOCUMENT_ROOT'].'/main.inc.php';
require_once __DIR__.'/../lib/main.lib.php';
require_once __DIR__.'/../class/ShippingSopService.class.php';
require_once DOL_DOCUMENT_ROOT.'/custom/chinaplanetcustomercenter/lib/admin_shell.lib.php';
chinaplanetsp_require_sop($user, 'sopread');
$service = new ShippingSopService($db); $id=GETPOSTINT('id'); $action=GETPOST('action','aZ09');
$canWrite=chinaplanetsp_can_sop($user,'sopwrite'); $canPublish=chinaplanetsp_can_sop($user,'soppublish'); $canDelete=chinaplanetsp_can_sop($user,'sopdelete');
try {
    if ($action==='publish') { chinaplanetsp_require_sop($user,'soppublish'); $service->publish($id,(int)$user->id); setEventMessages('SOP revision published.',null,'mesgs'); }
    elseif ($action==='archive') { chinaplanetsp_require_sop($user,'soppublish'); $service->archive($id,(int)$user->id); setEventMessages('SOP archived.',null,'mesgs'); }
    elseif ($action==='restore') { chinaplanetsp_require_sop($user,'soppublish'); $service->restore($id,(int)$user->id); setEventMessages('SOP restored.',null,'mesgs'); }
    elseif ($action==='restore_revision') { chinaplanetsp_require_sop($user,'soppublish'); $service->restoreRevision($id,GETPOSTINT('revision'),(int)$user->id,GETPOST('change_summary','alphanohtml')); setEventMessages('Older revision restored as a new published revision.',null,'mesgs'); }
    elseif ($action==='delete') { chinaplanetsp_require_sop($user,'sopdelete'); $service->delete($id,(int)$user->id); setEventMessages('SOP deleted from the working library; audit revisions were retained.',null,'mesgs'); header('Location: index.php'); exit; }
} catch(Throwable $e) { setEventMessages($e->getMessage(),null,'errors'); }
$sop=$service->get($id,$canWrite||$canPublish||$canDelete); if(!$sop) accessforbidden(); $revisions=$service->getRevisions($id);
$statusLabels=array('-1'=>'Deleted','0'=>'Draft','1'=>'Active','9'=>'Archived'); $revisionLabels=array(0=>'Draft',1=>'Published',9=>'Superseded');
$morecss=array(cpcc_admin_shell_asset('/custom/chinaplanetcustomercenter/css/admin_dashboard.css'),cpcc_admin_shell_asset('/custom/chinaplanetshippingprices/css/shippingprices.css')); llxHeader('',dol_escape_htmltag($sop['title']),'','',0,0,array(),$morecss);
cpcc_admin_shell_open('sop','SOP '.$sop['ref'],'Controlled internal procedure · revision '.$sop['revision_no'],'fa-clipboard-check');
$postButton=function($action,$label,$class='button',$confirm='')use($id){print '<form method="post"'.($confirm?' onsubmit="return confirm(\''.dol_escape_js($confirm).'\')"':'').'><input type="hidden" name="token" value="'.newToken().'"><input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="action" value="'.$action.'"><button class="'.$class.'">'.$label.'</button></form>';};
print '<main class="chinaplanetsp-sop-page"><div class="chinaplanetsp-sop-toolbar"><a class="button" href="index.php">Back to library</a><a class="button" target="_blank" href="print.php?id='.$id.'"><span class="fas fa-print"></span> Print</a>'; if($canWrite)print '<a class="button" href="edit.php?id='.$id.'">Edit / new revision</a>'; if($canPublish&&(int)$sop['revision_status']===0)$postButton('publish','Publish revision','button button-save','Publish this draft revision?'); if($canPublish&&(int)$sop['status']===1)$postButton('archive','Archive','button','Archive this SOP?'); if($canPublish&&(int)$sop['status']===9)$postButton('restore','Restore','button button-save'); if($canDelete)$postButton('delete','Delete','button button-delete','Delete this SOP from the working library? Revision history will remain.'); print '</div>';
print '<article class="chinaplanetsp-sop-detail"><header><div><span class="chinaplanetsp-badge">'.dol_escape_htmltag($sop['ref']).'</span><span class="chinaplanetsp-sop-status">'.dol_escape_htmltag($statusLabels[(string)$sop['status']]??'').'</span><h1>'.dol_escape_htmltag($sop['title']).'</h1>'; if($sop['title_ar'])print '<h2 dir="rtl">'.dol_escape_htmltag($sop['title_ar']).'</h2>'; print '</div><dl><dt>Revision</dt><dd>'.(int)$sop['revision_no'].'</dd><dt>Effective</dt><dd>'.dol_escape_htmltag($sop['effective_date']?:'Not set').'</dd><dt>Department</dt><dd>'.dol_escape_htmltag($sop['responsible_department']?:'Not assigned').'</dd><dt>Created by</dt><dd>'.dol_escape_htmltag($sop['created_by']?:'—').' · '.dol_escape_htmltag($sop['date_creation']).'</dd><dt>Updated by</dt><dd>'.dol_escape_htmltag($sop['updated_by']?:'—').' · '.dol_escape_htmltag($sop['tms']).'</dd></dl></header>';
$scope=array('Category'=>$sop['category_label']?:'All','Country'=>$sop['country_code']?:'All','POL'=>$sop['pol']?:'All','POD'=>$sop['pod']?:'All','Shipping line'=>$sop['shipping_line']?:'All','Service'=>ucfirst($sop['service_type']?:'all'),'Container'=>$sop['container_type']?:'All','Incoterm'=>$sop['incoterm']?:'All','Cargo'=>$sop['cargo_type']?:'All'); print '<section><h3>When this SOP applies / متى يطبق</h3><p>'.nl2br(dol_escape_htmltag($sop['applicability']?:'General procedure')).'</p><div class="chinaplanetsp-sop-scope-grid">';foreach($scope as$k=>$v)print'<div><span>'.$k.'</span><strong>'.dol_escape_htmltag($v).'</strong></div>';print'</div></section>';
$renderList=function($title,$value,$ordered=false,$warning=false){$items=ShippingSopService::decodeList($value);if(!$items)return;print '<section class="'.($warning?'chinaplanetsp-sop-warnings':'').'"><h3>'.$title.'</h3><'.($ordered?'ol':'ul').'>';foreach($items as$item)print'<li>'.nl2br(dol_escape_htmltag($item)).'</li>';print'</'.($ordered?'ol':'ul').'></section>';};
$renderList('Required information / المعلومات المطلوبة',$sop['required_information']); $renderList('Procedure steps / خطوات الإجراء',$sop['procedure_steps'],true); $renderList('Required documents / المستندات المطلوبة',$sop['required_documents']); $renderList('Important warnings / تحذيرات مهمة',$sop['warnings'],false,true);
if($sop['escalation_instructions'])print'<section class="chinaplanetsp-sop-escalation"><h3>Escalation instructions / تعليمات التصعيد</h3><p>'.nl2br(dol_escape_htmltag($sop['escalation_instructions'])).'</p></section>'; if($sop['internal_notes'])print'<section><h3>Internal notes / ملاحظات داخلية</h3><p>'.nl2br(dol_escape_htmltag($sop['internal_notes'])).'</p></section>'; if($sop['change_summary'])print'<footer><strong>Revision change:</strong> '.dol_escape_htmltag($sop['change_summary']).'</footer>'; print'</article>';
print '<section class="chinaplanetsp-rule-list"><div class="chinaplanetsp-list-head"><h2>Revision history <span>'.count($revisions).'</span></h2></div><div class="div-table-responsive"><table class="noborder centpercent"><thead><tr class="liste_titre"><th>Revision</th><th>Status</th><th>Effective</th><th>Change summary</th><th>Changed by</th><th>Date</th><th>Action</th></tr></thead><tbody>';foreach($revisions as$r){print'<tr><td><strong>Rev '.(int)$r['revision_no'].'</strong></td><td>'.dol_escape_htmltag($revisionLabels[(int)$r['revision_status']]??'').'</td><td>'.dol_escape_htmltag($r['effective_date']?:'—').'</td><td>'.dol_escape_htmltag($r['change_summary']?:'—').'</td><td>'.dol_escape_htmltag($r['user_login']?:'—').'</td><td>'.dol_escape_htmltag($r['tms']).'</td><td><a class="button smallpaddingimp" target="_blank" href="print.php?id='.$id.'&revision='.(int)$r['revision_no'].'">View</a>';if($canPublish&&(int)$r['revision_no']!==(int)$sop['revision_no'])print'<form method="post" class="inline-block" onsubmit="return confirm(\'Restore this version as a new published revision?\')"><input type="hidden" name="token" value="'.newToken().'"><input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="action" value="restore_revision"><input type="hidden" name="revision" value="'.(int)$r['revision_no'].'"><button class="button smallpaddingimp">Restore</button></form>';print'</td></tr>';}print'</tbody></table></div></section></main>';
cpcc_admin_shell_close();llxFooter();$db->close();
